                  "drop": [
                    "ALL"
                  ]
                },
                "privileged": false,
                "readOnlyRootFilesystem": true,
                "allowPrivilegeEscalation": false
              }
            }
          ],
          "restartPolicy": "Always",
          "terminationGracePeriodSeconds": 5,
          "dnsPolicy": "ClusterFirst",
          "serviceAccountName": "loadgenerator",
